const GAME_VERSION = "{{VERSION}}";
const SCHEMA_VERSION = 6;
/* One deliberate global reset. Keep this epoch unchanged in future normal releases. */
const SAVE_EPOCH='2026-10-23-reset-1';
const SAVE_LOCAL_KEY='tlr-kyushu-auto-'+SAVE_EPOCH;
const SAVE_DB_NAME='toplivermichi-kyushu-'+SAVE_EPOCH;
const SAVE_LOCK_NAME='toplivermichi-kyushu-owner-'+SAVE_EPOCH;
function currentSaveState(s){return !!s&&s.schemaVersion===SCHEMA_VERSION&&s.saveEpoch===SAVE_EPOCH;}
function validSaveRecord(r){if(!r||r.app!=='toplivermichi-kyushu'||typeof r.state!=='string'||checksum(r.state)!==r.sum)return false;try{const st=JSON.parse(r.state);validateState(st);return true;}catch(e){return false;}}
function foreignSaveRecord(r){try{return !!r&&typeof r.state==='string'&&JSON.parse(r.state).saveEpoch!==SAVE_EPOCH;}catch(e){return false;}}
function legacySaveLocalKey(key){return typeof key==='string'&&key!==SAVE_LOCAL_KEY&&/^tlr-kyushu-(?:auto|save)(?:-|$)/.test(key);}
function cleanupLegacyLocalSaves(){const out={removed:[],failed:false};try{const keys=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(legacySaveLocalKey(k))keys.push(k);}for(const key of keys){localStorage.removeItem(key);out.removed.push(key);}}catch(e){out.failed=true;}return out;}
let resetCleanupPromise=null;
function cleanupLegacySaves(){if(resetCleanupPromise)return resetCleanupPromise;resetCleanupPromise=(async()=>{const local=cleanupLegacyLocalSaves(),status={localRemoved:local.removed,localFailed:local.failed,deleted:[],pending:[],failed:[]};const names=new Set(['toplivermichi-kyushu']);try{if(typeof indexedDB!=='undefined'&&typeof indexedDB.databases==='function'){const list=await storageDeadline(indexedDB.databases());for(const row of list)if(row.name&&row.name!==SAVE_DB_NAME&&(row.name==='toplivermichi-kyushu'||row.name.startsWith('toplivermichi-kyushu-')))names.add(row.name);}}catch(e){}for(const name of names){if(name===SAVE_DB_NAME)continue;await new Promise(resolve=>{let settled=false;const finish=(kind)=>{if(!status[kind].includes(name))status[kind].push(name);if(!settled){settled=true;clearTimeout(timer);resolve();}};const timer=setTimeout(()=>finish('pending'),1200);try{const r=indexedDB.deleteDatabase(name);r.onblocked=()=>finish('pending');r.onerror=()=>finish('failed');r.onsuccess=()=>{status.pending=status.pending.filter(n=>n!==name);finish('deleted');};}catch(e){finish('failed');}});}G.resetCleanup=status;return status;})();return resetCleanupPromise;}
window.addEventListener('storage',e=>{if(legacySaveLocalKey(e.key))cleanupLegacyLocalSaves();});


