const ENEMY_TUNE = { hp:2.35, def:3, atkMul:1.85, atkAdd:5, rarHp:0.16, rarAtk:0.1, rageAt:0.45, rage:1.35, bossHp:2.6, bossAtk:1.9, bossAdd:6, bossRage:1.25, bossRageAt:0.4 };
/* 出現数：r=0..99。前半（強度5未満）1体40%・2体45%・3体15%／後半 1体25%・2体50%・3体25% */
function encounterSize(q, r){ r=Math.max(0,Math.min(99,r|0)); return q<5 ? (r<40?1:r<85?2:3) : (r<25?1:r<75?2:3); }
// 装備・職業熟練度を含む攻略目安。入場を制限するレベルではない。
const areaRequiredLevel=q=>Math.min(999,Math.ceil(q*1.25)+2);
const areaRecommendedLevel=q=>Math.min(999,Math.ceil(q*1.5)+5);
const bossRecommendedLevel=q=>Math.min(999,Math.ceil(q*1.5)+7);
function areaStrength(q){return {hp:1.12+Math.min(0.48,q*0.008),atk:1.08+Math.min(0.32,q*0.006),def:Math.ceil(q/12)};}
function autoAllowed(run){return !!run&&['field','boss','challenge'].includes(run.kind);}
function enforceAutoAvailability(run){if(run&&!autoAllowed(run)){clearTimeout(G.autoT);G.auto=false;G.autoWait=false;G.autoAct=null;G.autoLast=null;}}

function bossScale(bid, n){ n=Math.min(4,Math.max(1,n)); const o=BOSS_SCALE_OVERRIDE[bid]; return (o&&o[n]) || BOSS_PARTY_SCALE[n]; }

