function planExtraSkill(run,a,act,p,h){
 const sk=EXTRA_SKILLS[act.skillId];if(!sk||!(a.extraSkills||[]).includes(sk.id)){p.ok=false;p.reason='この技は未習得です。';return;}
 if(!battleGearSkillAvailable(a,sk)){p.ok=false;p.reason='対応する超レア装備を着けている間だけ使えます。';return;}
 if(sk.ultimate)return planCharacterUltimate(run,a,sk,p,h);
 if(sk.baseJob){planSkill(run,a,{...act,skillId:null,castJob:sk.baseJob},p,{...h,S:Kof(Math.min(run.levelCap||100,rankOf((a.jobRanks||{})[sk.baseJob]||0)))});if(p.ok){p.tech=sk.id;p.techCooldown=0;}return;}
 if(((a.skillReady||{})[sk.id]||0)>run.turn){p.ok=false;p.reason='再使用まで'+(a.skillReady[sk.id]-run.turn)+'ターンです。';return;}
 if(!h.payC(sk.cost))return;const{S,V,L}=h,k=sk.power;
 if(['strike','pierce'].includes(sk.effect)){if(!h.attackSingle(Math.floor((12+2*S)*k),{ignoreDef:sk.effect==='pierce'})){p.ok=false;p.reason='対象の敵を選んでください。';return;}}
 if(sk.effect==='all'){for(const e of h.en){const d=Math.max(1,Math.floor(((a.str||10)*0.65+(8+S)*V)*k)-effectiveEnemyDefense(a,e));p.dmg.push({slot:e.slot,amt:Math.min(d,e.hp),raw:d});}p.all=true;p.valid=true;p.aGain+=5;}
 if(sk.effect==='heal'||sk.effect==='ward'||sk.effect==='mp'){const t=h.needAlly(sk.effect==='mp');if(!t){p.ok=false;p.reason=sk.effect==='mp'?'自分以外の味方を選んでください。':'対象の味方を選んでください。';return;}if(sk.effect==='heal')h.heal(t,Math.floor(((18+2*S)*V+L)*k));if(sk.effect==='ward')h.addWard(t,Math.floor(5*k));if(sk.effect==='mp')h.addC(t,Math.ceil((8+Math.floor(L/10))*k));}
 if(sk.effect==='healAll')for(const t of h.al)h.heal(t,Math.floor(((10+S)*V+L/2)*k));
 if(sk.effect==='wardAll')for(const t of h.al)h.addWard(t,Math.floor(4*k));
 if(sk.effect==='rally'){h.gainA(Math.floor((24+S)*k));for(const t of h.al)h.addWard(t,1);}
 if(!p.valid){p.ok=false;p.reason='今は効果がありません。';return;}p.tech=sk.id;p.techCooldown=sk.cooldown;
}
