const RARE_ITEMS = {1:["IT126","IT102","IT104"],2:["IT126","IT127","IT129","IT125"],3:["IT127","IT129","IT125","IT117","IT128","IT130"]};
function rareTier(q){ return q<25?1:q<45?2:3; }
function giveGear(st,id,res,why){ if(typeof id!=='string'||!Object.prototype.hasOwnProperty.call(EQUIP,id))return false;res.gear=res.gear||[];
  if(eqCanAdd(st,id,1)){ st.owned[id]=Math.min(8,(st.owned[id]||0)+1); res.gear.push({id,why});collectionMark(st,id); return true; }
  st.keep=st.keep||[]; if(st.keep.length<KEEP_MAX){ st.keep.push(id); res.gear.push({id,why,kept:true});collectionMark(st,id); return true; } return false; }
function rareDrop(st, run, e, res){
  const r=e.rarity||1; const den = r>=5?5 : r>=4?12 : r>=3?40 : 150;
  if(randInt(den)!==0) return;
  const t=rareTier(run.q);
  if(randInt(10)<3){ const pool=["RRW","RRA","RRX"].map(x=>x+t); giveGear(st, pool[randInt(3)], res, `${e.display}のレアドロップ`); }
  else { const pool=RARE_ITEMS[t]; giveItem(st, pool[randInt(pool.length)], 1, res, `${e.display}のレアドロップ`); }
}
function rareBossDrop(st, run, first, res){
  const t=rareTier(run.q); const b=BOSSES[run.bossId]; const name=b?b.name:"ボス";
  if(first || randInt(3)===0){ const pool=["RRW","RRA","RRX"].map(x=>x+t); giveGear(st, pool[randInt(3)], res, `${name}${first?"の初回撃破":"のレアドロップ"}`); }
  if(randInt(2)===0){ const pool=RARE_ITEMS[t]; giveItem(st, pool[randInt(pool.length)], 1, res, `${name}が落とした`); }
}
