/* ---- 並び替え ---- */
function eqPower(it){ return (it.atk||0)+3*(it.d||0)+0.5*(it.hp||0)+1.5*(it.crit||0)+6*(it.c||0)+0.6*(it.commentA||0)+0.6*(it.meter||0)+0.8*(it.family||0)+3*(it.rest||0)+(it.pouch?15:0); }
const SLOT_ORDER={w:0,a:1,acc:2};
function sortEq(ids){ const m=G.eqSort||"type"; const P=id=>eqPower(EQUIP[id]);
  const jo=id=>EQUIP[id].job?1+JOB_IDS.indexOf(EQUIP[id].job):0;
  return ids.slice().sort((x,y)=>{ const a=EQUIP[x],b=EQUIP[y];
    if(m==="power") return P(y)-P(x);
    if(m==="price") return (b.price||0)-(a.price||0) || P(y)-P(x);
    if(m==="job") return jo(x)-jo(y) || SLOT_ORDER[a.slot]-SLOT_ORDER[b.slot] || P(y)-P(x);
    return SLOT_ORDER[a.slot]-SLOT_ORDER[b.slot] || P(y)-P(x); }); }
function eqSortBar(){ const m=G.eqSort||"type"; return `<div class="sortbar"><span class="small">並び替え</span>${[["type","種別"],["job","職業"],["power","強さ"],["price","価格"]].map(([v,l])=>`<button class="chip ${m===v?"on":""}" data-a="eqSort" data-v="${v}">${l}</button>`).join("")}</div>`; }
const ITEM_KIND_ORDER={"回復道具":0,"蘇生道具":1,"攻撃道具":2};
function sortItems(list){ const m=G.itSort||"type"; return list.slice().sort((x,y)=>{ const a=ITEMS[x.id||x],b=ITEMS[y.id||y];
  if(m==="stars") return b.stars-a.stars || a.tier-b.tier;
  if(m==="count") return (y.n||0)-(x.n||0);
  return ITEM_KIND_ORDER[itemKind(a)]-ITEM_KIND_ORDER[itemKind(b)] || a.cat.localeCompare(b.cat) || a.tier-b.tier; }); }
function itSortBar(withCount){ const m=G.itSort||"type"; return `<div class="sortbar"><span class="small">並び替え</span>${[["type","種別"],["stars","レア度"],...(withCount?[["count","所持数"]]:[])].map(([v,l])=>`<button class="chip ${m===v?"on":""}" data-a="itSort" data-v="${v}">${l}</button>`).join("")}</div>`; }
function canEquipC(st,c,it){return !!it&&characterLevel(st,c)>=(it.needL||1)&&(!it.job||(st.jobs[c]===it.job&&jobRank(st,c,it.job)>=it.needR));}
function equipRequirement(it){return it.job?[(it.needL>1?'個人Lv'+it.needL+'以上':''),JOBS[it.job].name+'専用・熟練度'+it.needR+'以上'].filter(Boolean).join('／'):'個人Lv'+(it.needL||1)+'以上';}

function bestGainText(st,id,L){ const it=EQUIP[id]; let best=null;
  for(const c of st.roster){ if(!canEquipC(st,c,it)) continue; const cur=charStats(st,c,L), nx=charStats(st,c,L,null,{...st.equip[c],[it.slot]:id});
    const a=statRows(cur,L), b=statRows(nx,L);
    for(let i=0;i<a.length;i++){ if(typeof a[i][1]!=="number") continue; const d=round1(b[i][1]-a[i][1]); if(d>0&&(!best||i<best.i||(i===best.i&&d>best.d))) best={d,k:a[i][0],c,i}; } }
  return best?`最大で${best.k}▲＋${best.d}（${charName(st,best.c)}）`:"今の装備より上がる人なし"; }
function whoCanText(st,it){ const w=st.roster.filter(c=>canEquipC(st,c,it)).map(c=>charName(st,c)); return w.length?`装備できる：${w.slice(0,4).join("・")}${w.length>4?`ほか${w.length-4}人`:""}`:"今は誰も装備できない"; }
function shopWhoHtml(st,id,L){ const it=EQUIP[id];
  return `<h3 class="label">誰が装備できて、どう変わるか</h3><div class="stack">${st.roster.map(c=>{ const ok=canEquipC(st,c,it); const cur=charStats(st,c,L); const now=st.equip[c][it.slot];
    return `<div class="jcard"><div class="srow"><b>${esc(charName(st,c))}</b><span class="small">${esc(JOBS[st.jobs[c]].name)}・今の${EQ_SLOT_NAME[it.slot]}：${now?esc(EQUIP[now].name):"なし"}</span></div>${ok?statDiffHtml(cur,charStats(st,c,L,null,{...st.equip[c],[it.slot]:id}),L):`<p class="small warn">装備できません（${esc(equipRequirement(it))}）。</p>`}</div>`; }).join("")}</div>`; }
/* ---- レベルアップの詳しい内訳 ---- */
function levelUpDetail(st, L0, L1){
  if(L1<=L0) return null; const out={};
  for(const cid of st.party){ const a=charStats(st,cid,L0,null,null,true), b=charStats(st,cid,L1,null,null,true); const sig=JOB_SIG[a.job];
    const rows=[["最大HP",a.maxHP,b.maxHP,"main"],["最大MP",a.startC,b.startC,"main"],["攻撃力",attackPower(a,L0),attackPower(b,L1),"main"],["防御力",defensePower(a,L0),defensePower(b,L1),"main"],
      ...STAT_KEYS.map(k=>[STAT_NAMES[k]+(k===sig?"★":""),a.base[k],b.base[k],k===sig?"sig":""])];
    out[cid]={job:a.job, rows}; }
  return out; }
function levelUpHtml(st, det){ if(!det) return "";
  return `<div class="rbox rups"><h3 class="label">能力アップ（★は職業の看板能力）</h3><div class="lvgrid">${Object.entries(det).filter(([c])=>st.roster.includes(c)).map(([c,d])=>{
    const max=Math.max(1,...d.rows.map(r=>r[2]-r[1]));
    return `<div class="lvcard"><div class="lvh"><b>${esc(charName(st,c))}</b><span class="small">${esc(JOBS[d.job].name)}・成長：${esc(growthLabel(d.job))}</span></div><table class="lvt"><tbody>${d.rows.map(([n,a,b,cl])=>{ const g=b-a;
      return `<tr class="${cl}"><th>${n}</th><td>${a}</td><td class="ar">→</td><td><b>${b}</b></td><td class="${g>0?"up":"dim"}">${g>0?`＋${g}`:"±0"}</td><td class="lvbar"><i style="width:${Math.round(100*Math.max(0,g)/max)}%"></i></td></tr>`; }).join("")}</tbody></table></div>`; }).join("")}</div></div>`; }

function HUB_NAME_OF(id){ return (HUBS[id]&&HUBS[id].name) || ((KYUSHU.find(h=>h.id===id)||{}).name) || id; }
/* 本編の順番：前の拠点の本編依頼を終えると、次の拠点へ進める */
function mainQuestOf(hub){ return Object.keys(QUESTS).find(k=>QUESTS[k].main&&QUESTS[k].hub===hub); }
function hubRequirement(hub){const national=nationalEntry(hub);if(national)return national.prior;const c=NEXT_CHAPTER.find(c=>c.id===hub);if(c)return c.index?NEXT_CHAPTER[c.index-1].qid:'M16';if(hub==='KY17')return 'M16';const i=HUB_ORDER.indexOf(hub);return i>0?mainQuestOf(HUB_ORDER[i-1]):null;}
function hubUnlocked(st,hub){if(!HUB_ORDER.includes(hub)||hub.startsWith('NX')&&st.quests.M16!=='complete')return false;const q=hubRequirement(hub);return !q||st.quests[q]==='complete';}
function fixQuestChain(st){
  for(const id of Object.keys(QUESTS)) if(!st.quests[id]) st.quests[id]="locked";
  for(const hub of HUB_ORDER){const b=mainQuestOf(hub);if(b&&hubUnlocked(st,hub)&&st.quests[b]==='locked')st.quests[b]='available';}
  st.shikokuChugokuClear=st.quests.C09==='complete';st.nationalClear=st.quests.N607==='complete';
  for(const id of Object.keys(QUESTS)){ const Q=QUESTS[id]; if(Q.main&&st.quests[id]==="complete"&&Q.rank!=null) st.moeRank=Math.max(st.moeRank||0,Q.rank); }
}
function sideQuestOf(hub){ return Object.keys(QUESTS).find(k=>!QUESTS[k].main&&QUESTS[k].hub===hub); }

