const FACILITY = { railStation:{mark:"駅",name:"新幹線駅・街中から乗車",color:"#a9cfcc"}, landmark:{mark:"景",name:"名所・ランドマーク",color:"#d5b34c"},port:{mark:"港",name:"港・航路案内",color:"#83b9ae"}, cityEntry:{mark:"街",name:"街の入口",color:"#83B9AE"},worldExit:{mark:"外",name:"街外へ出る",color:"#D5B34C"}, station:{mark:"駅",name:"新幹線駅",color:"#83B9AE"}, shop:{mark:"店",name:"ショップ",color:"#D5B34C"}, inn:{mark:"宿",name:"宿屋",color:"#83B9AE"}, door:{mark:"控",name:"控室（実家）",color:"#E88470"}, gate:{mark:"道",name:"街の出口",color:"#C9BFA6"}, rest:{mark:"休",name:"休息",color:"#83B9AE"}, board:{mark:"編",name:"編成",color:"#D5B34C"} };

